def transform(grid):
    counts = {2: 0, 3: 0}
    for row in grid:
        i = 0
        while i < len(row):
            if row[i] in counts:
                color = row[i]
                counts[color] += 1
                while i < len(row) and row[i] == color:
                    i += 1
            else:
                i += 1
    cells = [3] * counts[3] + [2] * counts[2]
    cells = (cells + [0] * 6)[:6]
    return [cells[:3], cells[3:6]]
